import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String text, String word) {
        List<Integer> res = new ArrayList<>();
        int m = word.length();
        if (m > text.length()) return res;
        int[] need = new int[26], have = new int[26];
        for (char c : word.toCharArray()) need[c - 'a']++;
        for (int i = 0; i < text.length(); i++) {
            have[text.charAt(i) - 'a']++;                    // letter entering
            if (i >= m) have[text.charAt(i - m) - 'a']--;    // letter leaving
            if (i >= m - 1 && Arrays.equals(have, need)) res.add(i - m + 1);
        }
        return res;
    }
}

