class Solution:
    def findAnagrams(self, text: str, word: str) -> List[int]:
        m = len(word); need = Counter(word); win = Counter(); out = []
        for i, c in enumerate(text):
            win[c] += 1
            if i >= m:
                d = text[i - m]; win[d] -= 1
                if win[d] == 0: del win[d]
            if i >= m - 1 and win == need: out.append(i - m + 1)
        return out

