function findAnagrams(text, word) {
  const m = word.length, out = [];
  if (m > text.length) return out;
  const c = new Int32Array(26); let diff = 0;
  for (let i = 0; i < m; i++) c[word.charCodeAt(i) - 97]++;
  for (let i = 0; i < 26; i++) if (c[i]) diff++;
  const upd = (x, d) => { if (c[x] === 0) diff++; c[x] += d; if (c[x] === 0) diff--; };
  for (let i = 0; i < text.length; i++) {
    upd(text.charCodeAt(i) - 97, -1);
    if (i >= m) upd(text.charCodeAt(i - m) - 97, 1);
    if (i >= m - 1 && diff === 0) out.push(i - m + 1);
  }
  return out;
}
